/**
 * Builds the account portal's passkey script: type-checks `passkey.ts` against the DOM, then
 * bundles it with esbuild into `../passkey-script.generated.ts`, a string constant the portal
 * serves at `/account/passkey.js`.
 *
 *   npx tsx mcp/sasha-slides/http/passkey-browser/build.ts          (from the repo root)
 *
 * WHY A CHECKED-IN GENERATED FILE rather than bundling at server start: esbuild is a
 * development dependency of the repo, not a runtime dependency of the connector image
 * (`deploy/package.json`), and a generated TypeScript module is reached through an ordinary
 * import, so `deploy/context-files.ts` ships it with no list to edit. The same pattern as
 * `sasha-icon.generated.ts`. `test/passkey-script.test.ts` fails when the generated file no
 * longer matches its source, so an edit that skipped this build cannot go unnoticed.
 */
import { execFileSync } from "node:child_process";
import { writeFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { build } from "esbuild";

export const PASSKEY_SCRIPT_SOURCE = join(import.meta.dirname, "passkey.ts");
export const PASSKEY_SCRIPT_MODULE = join(import.meta.dirname, "..", "passkey-script.generated.ts");
const REPO_ROOT = join(import.meta.dirname, "..", "..", "..", "..");

/** The generated module's full text, from the current source. */
export async function renderPasskeyScriptModule(): Promise<string> {
  const result = await build({
    // Fixed, so the source path esbuild writes into the output does not depend on the caller's cwd.
    absWorkingDir: REPO_ROOT,
    entryPoints: [PASSKEY_SCRIPT_SOURCE],
    bundle: true,
    format: "iife",
    platform: "browser",
    target: "es2020",
    minify: false,
    write: false,
    logLevel: "error",
  });
  const code = result.outputFiles[0]?.text;
  if (code === undefined) throw new Error(`esbuild produced no output for ${PASSKEY_SCRIPT_SOURCE}`);
  return `// Generated by http/passkey-browser/build.ts from http/passkey-browser/passkey.ts. Do not edit.\nexport const PASSKEY_SCRIPT = ${JSON.stringify(code)};\n`;
}

async function main(): Promise<void> {
  // esbuild strips types without checking them, so the check is its own failing step first.
  execFileSync(join(REPO_ROOT, "node_modules", ".bin", "tsc"), ["--noEmit", "-p", import.meta.dirname], { stdio: "inherit" });
  writeFileSync(PASSKEY_SCRIPT_MODULE, await renderPasskeyScriptModule());
  process.stdout.write(`wrote ${PASSKEY_SCRIPT_MODULE}\n`);
}

if (process.argv[1] !== undefined && resolve(process.argv[1]) === import.meta.filename) void main();
